  void AddField(SettingField f){var g=new Grid{Margin=new Thickness(0,0,0,16)};g.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(0.42,GridUnitType.Star)});g.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});var labels=new StackPanel{Margin=new Thickness(0,3,20,0)};labels.Children.Add(new TextBlock{Text=f.Label,TextWrapping=TextWrapping.Wrap});if(!String.IsNullOrEmpty(f.Help))labels.Children.Add(new TextBlock{Text=f.Help,FontSize=11.5,Foreground=Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,0)});g.Children.Add(labels);FrameworkElement input;var binding=new Binding("Value"){Source=f,Mode=BindingMode.TwoWay,UpdateSourceTrigger=UpdateSourceTrigger.PropertyChanged};if(f.Kind=="bool"){var c=new CheckBox{VerticalAlignment=VerticalAlignment.Top,Margin=new Thickness(0,6,0,0),Foreground=TextColor,Content="사용"};c.SetBinding(CheckBox.IsCheckedProperty,binding);input=c;}else if(f.Kind=="choice"||f.Kind=="int-choice"){if(f.Kind=="int-choice")f.Value=Convert.ToString(f.Value,CultureInfo.InvariantCulture);var c=new ComboBox{ItemsSource=f.Options.Select(x=>new ChoiceOption(x,ChoiceLabel(f,x))).ToArray(),DisplayMemberPath="Value",SelectedValuePath="Key",VerticalAlignment=VerticalAlignment.Top,Padding=new Thickness(6,5,6,5)};c.SetBinding(ComboBox.SelectedValueProperty,binding);input=c;}else{var t=new TextBox{VerticalAlignment=VerticalAlignment.Top};if(f.Kind=="int")t.PreviewTextInput+=delegate(object sender,System.Windows.Input.TextCompositionEventArgs e){e.Handled=!System.Text.RegularExpressions.Regex.IsMatch(e.Text,"^[0-9]+$");};t.SetBinding(TextBox.TextProperty,binding);input=t;}AutomationProperties.SetName(input,f.Label);Grid.SetColumn(input,1);g.Children.Add(input);content.Children.Add(g);}
  void Run(Func<string> action,Action success=null,string operation=null){if(busy)return;busy=true;pageActionHost.IsEnabled=false;apply.IsEnabled=false;navigation.IsEnabled=false;content.IsEnabled=false;discard.IsEnabled=false;undo.IsEnabled=false;vm.Status=(operation??"설정 / 구성 요소 작업")+" 처리 중…";Task.Factory.StartNew(action).ContinueWith(t=>Dispatcher.BeginInvoke((Action)delegate{busy=false;pageActionHost.IsEnabled=true;navigation.IsEnabled=true;content.IsEnabled=true;if(t.IsFaulted){vm.Status="작업 실패: "+t.Exception.GetBaseException().Message;RestoreNavSelection();}else{vm.Status=t.Result;if(page=="appearance")RefreshFont();if(success!=null)success();RefreshPaletteShortcut();vm.Status=t.Result;}UpdateDirty();RefreshUx();}));}

  void LoadSensors(){var s=vm.Service.State("sensors");var values=s.ContainsKey("TemperatureReadings")?s["TemperatureReadings"] as IEnumerable:null;var items=new List<ComboBoxItem>();if(values!=null)foreach(var value in values){var d=value as Dictionary<string,object>;if(d!=null&&(Convert.ToString(d["Unit"])=="°C"||Convert.ToString(d["Unit"])=="W"))items.Add(new ComboBoxItem{Content=Convert.ToString(d["Sensor"])+" / "+d["Label"]+" · "+d["Formatted"]+" ["+d["Quality"]+"]",Tag=d});}sensorPicker.ItemsSource=items;if(connectSensor!=null)connectSensor.IsEnabled=items.Any(x=>Convert.ToString(((Dictionary<string,object>)x.Tag)["Quality"])=="valid");if(items.Count>0)sensorPicker.SelectedIndex=0;RefreshReport();}
  string SaveSensor(){Dictionary<string,object> reading=null;string metric=null;Dispatcher.Invoke((Action)delegate{var i=sensorPicker.SelectedItem as ComboBoxItem;reading=i==null?null:i.Tag as Dictionary<string,object>;metric=Convert.ToString(metricPicker.SelectedValue);});if(reading==null||Convert.ToString(reading["Quality"])!="valid")throw new ArgumentException("최신 센서 값을 먼저 선택하세요.");if(Convert.ToString(reading["Unit"])!=(metric=="CpuPackagePowerW"?"W":"°C"))throw new ArgumentException("선택한 센서의 단위가 다릅니다.");var sourceSensor=Convert.ToString(reading["Sensor"]);if((metric=="CpuTemperatureC"||metric=="CpuPackagePowerW")&&sourceSensor.IndexOf("CPU [",StringComparison.OrdinalIgnoreCase)<0)throw new ArgumentException("CPU 장치의 실제 센서를 선택하세요.");if(metric=="GpuTemperatureC"&&sourceSensor.IndexOf("GPU [",StringComparison.OrdinalIgnoreCase)<0&&sourceSensor.IndexOf("iGPU [",StringComparison.OrdinalIgnoreCase)<0)throw new ArgumentException("GPU 장치의 실제 센서를 선택하세요.");Dictionary<string,object> physicalDisk=null;if(metric=="SsdTemperatureC"){var topology=vm.Service.State("storage-topology");if(topology.ContainsKey("Volumes"))foreach(var entry in (IEnumerable)topology["Volumes"]){var d=entry as Dictionary<string,object>;if(d!=null&&d.ContainsKey("DiskModel")&&sourceSensor.IndexOf(Convert.ToString(d["DiskModel"]),StringComparison.OrdinalIgnoreCase)>=0){physicalDisk=d;break;}}if(physicalDisk==null)throw new ArgumentException("Windows 물리 디스크 모델과 일치하는 온도 센서를 선택하세요.");}var fresh=vm.Service.SensorSnapshot();var available=(System.Collections.IEnumerable)fresh["TemperatureReadings"];reading=available.Cast<object>().OfType<Dictionary<string,object>>().FirstOrDefault(x=>DesktopService.S(x,"Fingerprint")==DesktopService.S(reading,"Fingerprint")&&DesktopService.S(x,"Quality")=="valid");if(reading==null)throw new ArgumentException("선택한 센서가 더 이상 최신 상태가 아닙니다. 다시 읽어 주세요.");var c=vm.Service.Read("sensors");var original=vm.Service.Json.Serialize(c["mappings"]);var mappings=new List<object>();if(c.ContainsKey("mappings"))foreach(var x in (IEnumerable)c["mappings"]){var d=x as Dictionary<string,object>;if(d!=null&&Convert.ToString(d["metric"])!=metric)mappings.Add(d);}var oldMapping=((IEnumerable)c["mappings"]).Cast<object>().OfType<Dictionary<string,object>>().FirstOrDefault(x=>DesktopService.S(x,"metric")==metric);var selectedMapping=oldMapping==null?new Dictionary<string,object>():new Dictionary<string,object>(oldMapping);selectedMapping["metric"]=metric;selectedMapping["fingerprint"]=reading["Fingerprint"];selectedMapping["sensor"]=reading["Sensor"];selectedMapping["label"]=reading["Label"];selectedMapping["index"]=reading["Index"];selectedMapping["unit"]=reading["Unit"];if(physicalDisk!=null){selectedMapping["diskUniqueId"]=physicalDisk["DiskUniqueId"];selectedMapping["diskNumber"]=physicalDisk["DiskNumber"];}mappings.Add(selectedMapping);vm.Service.Apply(new[]{new SettingField{Config="sensors",Key="mappings",Kind="object",Label="센서 연결",Original=original,Value=mappings}});var check=vm.Service.SensorSnapshot();if(check[metric]==null){try{vm.Service.Undo();}catch(Exception rollback){throw new InvalidOperationException("센서 연결 확인 실패·복구 확인 필요: "+rollback.Message);}throw new InvalidOperationException("센서 연결 확인에 실패해 직전 연결로 복원했습니다.");}return "실제 센서 식별값을 저장하고 제공자에서 현재 값을 확인했습니다.";}
  void RefreshReport(){try{var lines=new List<string>();if(page=="windhawk"){
    var selected=modList==null?null:modList.SelectedItem as WindhawkEntry;var mods=vm.Service.WindhawkMods();
    if(modList!=null){modList.ItemsSource=mods;modList.SelectedItem=mods.FirstOrDefault(x=>selected!=null&&x.Id==selected.Id)??mods.FirstOrDefault();var item=modList.SelectedItem as WindhawkEntry;if(item!=null)lines.Add(item.Details);}
    lines.Insert(0,"설치 "+mods.Length+"개 · 활성 "+mods.Count(x=>x.Enabled)+"개");
   }else{
    foreach(var p in new[]{"Rainmeter","GUNT-Bar","windhawk","Lively","Flow.Launcher"}){var a=Process.GetProcessesByName(p);try{lines.Add(p+"  "+(a.Length>0?"실행 중 ("+a.Length+")":"중지 / 확인 필요"));}finally{foreach(var process in a)process.Dispose();}}
    var s=vm.Service.State("sensors");if(s.Count>0){lines.Add("");foreach(var k in new[]{"Timestamp","CpuModel","CpuTemperatureC","GpuTemperatureC","SsdTemperatureC","CpuPackagePowerW","TemperatureQuality","NetAdapter","NetLinkBitsPerSecond"})if(s.ContainsKey(k))lines.Add(k+"  "+(s[k]==null?"사용 불가":Convert.ToString(s[k])));}
    if(page=="displays"||page=="diagnostics")foreach(var monitor in System.Windows.Forms.Screen.AllScreens)lines.Add(monitor.DeviceName+" · "+monitor.Bounds+" · "+GuntLayout.Scale(monitor)*100+"%"+(monitor.Primary?" · 주 모니터":""));
    if(page=="displays"||page=="diagnostics"){var p=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run");lines.Add("시작 등록  "+(p==null?"없음":Convert.ToString(p.GetValue("GUNTDesktop","없음"))));if(p!=null)p.Dispose();}
    if(page=="wallpaper")lines.Add("현재 재생 제어\n"+vm.Service.Json.Serialize(vm.Service.State("wallpaper-playback")));
   }report.Text=String.Join("\n",lines);
  }catch(Exception e){report.Text="상태 확인 실패: "+e.Message;}}
  string SelectedModId(){return Dispatcher.Invoke(new Func<string>(()=>{var item=modList==null?null:modList.SelectedItem as WindhawkEntry;if(item==null||!Regex.IsMatch(item.Id,@"^[a-z0-9-]+$"))throw new InvalidOperationException("모드를 선택하세요.");return item.Id;}));}
  static string Match(string s,string regex){var m=Regex.Match(s,regex);return m.Success?m.Groups[1].Value.Trim():"확인 불가";}
  [DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr h,int attribute,ref int value,int size);
  [DllImport("user32.dll")]static extern bool SetWindowPos(IntPtr h,IntPtr after,int x,int y,int w,int height,uint flags);
  IntPtr WindowHook(IntPtr h,int msg,IntPtr wp,IntPtr lp,ref bool handled){if(msg==0x8004){Activate();var p=Path.Combine(root,"state","control-center-open.json");if(File.Exists(p))try{var d=vm.Service.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(p));SelectPage(Convert.ToString(d["page"]));}catch{}handled=true;}return IntPtr.Zero;}
  void SaveWindow(){try{GuntLayout.RECT r;if(GuntLayout.GetWindowRect(new WindowInteropHelper(this).Handle,out r))GuntConfiguration.Atomic(root,Path.Combine(root,"state","control-center-window.json"),vm.Service.Json.Serialize(new[]{r.Left,r.Top,r.Right-r.Left,r.Bottom-r.Top}),false);}catch{}}
  void RestoreWindow(){try{var p=Path.Combine(root,"state","control-center-window.json");if(!File.Exists(p)){GuntLayout.RECT current;GuntLayout.GetWindowRect(new WindowInteropHelper(this).Handle,out current);var work=System.Windows.Forms.Screen.PrimaryScreen.WorkingArea;int width=Math.Min(current.Right-current.Left,work.Width-24),height=Math.Min(current.Bottom-current.Top,work.Height-24);SetWindowPos(new WindowInteropHelper(this).Handle,IntPtr.Zero,work.Left+(work.Width-width)/2,work.Top+(work.Height-height)/2,width,height,0x14);return;}var r=vm.Service.Json.Deserialize<int[]>(File.ReadAllText(p));var screen=System.Windows.Forms.Screen.FromRectangle(new System.Drawing.Rectangle(r[0],r[1],r[2],r[3]));var w=screen.WorkingArea;SetWindowPos(new WindowInteropHelper(this).Handle,IntPtr.Zero,Math.Max(w.Left,Math.Min(r[0],w.Right-Math.Min(r[2],w.Width))),Math.Max(w.Top,Math.Min(r[1],w.Bottom-Math.Min(r[3],w.Height))),Math.Min(r[2],w.Width),Math.Min(r[3],w.Height),0x14);}catch{}}
 }
